const CLOUD='https://apis.roblox.com/cloud/v2/';
const TARGET='universes/9419478735/places/79738710219521/';
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function req(path,body){
 const key=process.env.ROBLOX_API_KEY;
 if(!key) throw new Error('Missing ROBLOX_API_KEY');
 let last;
 for(let i=0;i<8;i++){
  const res=await fetch(CLOUD+path,{
   method:body?'POST':'GET',
   headers:{'x-api-key':key,'content-type':'application/json'},
   body:body?JSON.stringify(body):undefined,
   signal:AbortSignal.timeout(60000)
  });
  const raw=await res.text();
  let data; try{data=JSON.parse(raw)}catch{data={raw}};
  if(res.ok) return data;
  if([429,500,502,503].includes(res.status)){
   last=new Error('HTTP '+res.status+': '+JSON.stringify(data));
   await sleep(Math.min(30000,3000*(i+1)));
   continue;
  }
  throw new Error('HTTP '+res.status+': '+JSON.stringify(data));
 }
 throw last||new Error('Request retries exhausted');
}
async function execute(script){
 let task=await req(TARGET+'luau-execution-session-tasks',{timeout:'240s',script});
 const deadline=Date.now()+360000;
 while(['QUEUED','PENDING','PROCESSING'].includes(task.state)){
  if(Date.now()>deadline) throw new Error('Quality hotfix timeout');
  await sleep(1200);
  task=await req(task.path);
 }
 if(task.state!=='COMPLETE'||task.error) throw new Error('Quality hotfix failed: '+JSON.stringify(task));
 const v=task?.output?.results?.[0];
 if(typeof v!=='string') return v??null;
 try{return JSON.parse(v)}catch{return v}
}
